1	package strategy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"os/exec"
10		"strings"
11		"sync"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/settings"
15	
16		"github.com/go-git/go-git/v6"
17		"github.com/go-git/go-git/v6/plumbing"
18		"github.com/go-git/go-git/v6/plumbing/object"
19	)
20	
21	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
22	// The target can be a remote name (e.g., "origin") or a URL for direct push.
23	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
24	// no remote tracking refs — git itself handles the no-op case.
25	// Does not check any settings — callers are responsible for gating.
26	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
27		repo, err := OpenRepository(ctx)
28		if err != nil {
29			return nil //nolint:nilerr // Hook must be silent on failure
30		}
31	
32		// Check if branch exists locally
33		branchRef := plumbing.NewBranchReferenceName(branchName)
34		localRef, err := repo.Reference(branchRef, true)
35		if err != nil {
36			// No branch, nothing to push
37			return nil //nolint:nilerr // Expected when no sessions exist yet
38		}
39	
40		// Only check remote tracking refs when target is a remote name (not a URL).
41		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
42		if !isURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
43			return nil
44		}
45	
46		return doPushBranch(ctx, target, branchName)
47	}
48	
49	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
50	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
51	func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
52		// Check for remote tracking ref: refs/remotes/<remote>/<branch>
53		remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
54		remoteRef, err := repo.Reference(remoteRefName, true)
55		if err != nil {
56			// Remote branch doesn't exist yet - we have content to push
57			return true
58		}
59	
60		// If local and remote point to same commit, nothing to sync
61		// This is the only case where we skip - any difference needs handling
62		return localHash != remoteRef.Hash()
63	}
64	
65	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
66	// The target can be a remote name or a URL.
67	func doPushBranch(ctx context.Context, target, branchName string) error {
68		displayTarget := target
69		if isURL(target) {
70			displayTarget = "checkpoint remote"
71		}
72	
73		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
74		stop := startProgressDots(os.Stderr)
75	
76		// Try pushing first
77		if result, err := tryPushSessionsCommon(ctx, target, branchName); err == nil {
78			finishPush(ctx, stop, result, target)
79			return nil
80		}
81		stop("")
82	
83		// Push failed - likely non-fast-forward. Try to fetch and rebase.
84		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
85		stop = startProgressDots(os.Stderr)
86	
87		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
88			stop("")
89			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
90			printCheckpointRemoteHint(target)
91			return nil // Don't fail the main push
92		}
93		stop(" done")
94	
95		// Try pushing again after rebase
96		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
97		stop = startProgressDots(os.Stderr)
98	
99		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
100			stop("")
101			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
102			printCheckpointRemoteHint(target)
103		} else {
104			finishPush(ctx, stop, result, target)
105		}
106	
107		return nil
108	}
109	
110	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
111	// Only prints when the target is a URL (not the user's default remote).
112	func printCheckpointRemoteHint(target string) {
113		if !isURL(target) {
114			return
115		}
116		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
117		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
118	}
119	
120	// settingsHintOnce ensures the settings commit hint prints at most once per process.
121	var settingsHintOnce sync.Once
122	
123	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
124	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
125	// entire.io discovers the external checkpoint repo by reading the committed project
126	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
127	// (not just in settings.local.json or uncommitted local changes).
128	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
129	// single pre-push invocation.
130	func printSettingsCommitHint(ctx context.Context, target string) {
131		if !isURL(target) {
132			return
133		}
134		settingsHintOnce.Do(func() {
135			if isCheckpointRemoteCommitted(ctx) {
136				return
137			}
138			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
139		})
140	}
141	
142	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
143	// at HEAD contains a valid checkpoint_remote configuration. This is the true
144	// discoverability check: entire.io reads from committed project settings, not from
145	// local overrides or uncommitted changes.
146	func isCheckpointRemoteCommitted(ctx context.Context) bool {
147		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
148		output, err := cmd.Output()
149		if err != nil {
150			return false // file doesn't exist at HEAD
151		}
152		// Parse the committed content and check for checkpoint_remote
153		committed, err := settings.LoadFromBytes(output)
154		if err != nil {
155			return false
156		}
157		return committed.GetCheckpointRemote() != nil
158	}
159	
160	// pushResult describes what happened during a push attempt.
161	type pushResult struct {
162		// upToDate is true when the remote already had all commits (nothing transferred).
163		upToDate bool
164	}
165	
166	// parsePushResult checks git push --porcelain output for ref status flags.
167	// In porcelain mode, each ref gets a tab-delimited status line:
168	//
169	//	<flag>\t<from>:<to>\t<summary>
170	//
171	// where flag '=' means the ref was already up-to-date. This is locale-independent,
172	// unlike the human-readable "Everything up-to-date" message.
173	func parsePushResult(output string) pushResult {
174		for _, line := range strings.Split(output, "\n") {
175			if strings.HasPrefix(line, "=\t") {
176				return pushResult{upToDate: true}
177			}
178		}
179		return pushResult{upToDate: false}
180	}
181	
182	// finishPush stops the progress dots and prints "already up-to-date" or "done"
183	// depending on the push result. Only prints the settings commit hint when new
184	// content was actually pushed.
185	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
186		if result.upToDate {
187			stop(" already up-to-date")
188		} else {
189			stop(" done")
190			printSettingsCommitHint(ctx, target)
191		}
192	}
193	
194	// tryPushSessionsCommon attempts to push the sessions branch.
195	func tryPushSessionsCommon(ctx context.Context, remote, branchName string) (pushResult, error) {
196		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
197		defer cancel()
198	
199		// Use --no-verify to prevent recursive hook calls.
200		// Use --porcelain for machine-readable, locale-independent output.
201		cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", "--porcelain", remote, branchName)
202	
203		output, err := cmd.CombinedOutput()
204		outputStr := string(output)
205		if err != nil {
206			// Check if it's a non-fast-forward error (we can try to recover)
207			if strings.Contains(outputStr, "non-fast-forward") ||
208				strings.Contains(outputStr, "rejected") {
209				return pushResult{}, errors.New("non-fast-forward")
210			}
211			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
212		}
213	
214		return parsePushResult(outputStr), nil
215	}
216	
217	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
218	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
219	// always apply cleanly.
220	// The target can be a remote name or a URL.
221	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
222		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
223		defer cancel()
224	
225		fetchTarget, err := ResolveFetchTarget(ctx, target)
226		if err != nil {
227			return fmt.Errorf("resolve fetch target: %w", err)
228		}
229	
230		// Determine fetch refspec. When the resolved fetch target is a URL, use a
231		// temp ref; when it's still a remote name, use the standard remote-tracking
232		// ref.
233		var fetchedRefName plumbing.ReferenceName
234		var refSpec string
235		usedTempRef := isURL(fetchTarget)
236		if usedTempRef {
237			tmpRef := "refs/entire-fetch-tmp/" + branchName
238			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
239			fetchedRefName = plumbing.ReferenceName(tmpRef)
240		} else {
241			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
242			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
243		}
244	
245		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
246		// Use --filter=blob:none for a partial fetch that downloads only commits
247		// and trees, skipping blobs. The merge only needs the tree structure to
248		// combine entries; blobs are already local or fetched on demand.
249		fetchArgs := AppendFetchFilterArgs(ctx, []string{"fetch", "--no-tags", fetchTarget, refSpec})
250		fetchCmd := CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
251		if output, err := fetchCmd.CombinedOutput(); err != nil {
252			return fmt.Errorf("fetch failed: %s", output)
253		}
254	
255		repo, err := OpenRepository(ctx)
256		if err != nil {
257			return fmt.Errorf("failed to open git repository: %w", err)
258		}
259	
260		// Reconcile disconnected metadata branches before rebasing.
261		// The fetch above updated the remote-tracking ref, so reconciliation
262		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
263		// this cherry-picks local commits onto remote tip, updating the local ref.
264		// If reconciliation fails, abort — proceeding to rebase on disconnected
265		// branches would silently combine unrelated histories.
266		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
267			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
268		}
269	
270		// Get local branch (re-read after potential reconciliation update)
271		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
272		if err != nil {
273			return fmt.Errorf("failed to get local ref: %w", err)
274		}
275	
276		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
277		remoteRef, err := repo.Reference(fetchedRefName, true)
278		if err != nil {
279			return fmt.Errorf("failed to get remote ref: %w", err)
280		}
281	
282		// If local is already at or behind remote, fast-forward
283		if localRef.Hash() == remoteRef.Hash() {
284			return nil
285		}
286	
287		// Find merge base
288		repoPath, err := getRepoPath(repo)
289		if err != nil {
290			return fmt.Errorf("failed to get repo path: %w", err)
291		}
292		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
293		if err != nil {
294			return fmt.Errorf("failed to find merge base: %w", err)
295		}
296	
297		// If local is ancestor of remote (merge base == local), fast-forward to remote
298		if mergeBase == localRef.Hash() {
299			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
300			if err := repo.Storer.SetReference(ref); err != nil {
301				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
302			}
303			if usedTempRef {
304				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
305			}
306			return nil
307		}
308	
309		// Collect commits reachable from local but not from remote and cherry-pick
310		// them onto the remote tip. This preserves local-only commits even when the
311		// local metadata branch already contains old merge commits, while avoiding
312		// replaying shared ancestors older than the true merge-base.
313		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
314		if err != nil {
315			return fmt.Errorf("failed to collect local commits: %w", err)
316		}
317	
318		if len(localCommits) == 0 {
319			// No local-only commits — just point to remote
320			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
321			if err := repo.Storer.SetReference(ref); err != nil {
322				return fmt.Errorf("failed to update branch ref: %w", err)
323			}
324			if usedTempRef {
325				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
326			}
327			return nil
328		}
329	
330		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
331		if err != nil {
332			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
333		}
334	
335		// Update branch ref
336		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
337		if err := repo.Storer.SetReference(newRef); err != nil {
338			return fmt.Errorf("failed to update branch ref: %w", err)
339		}
340	
341		// Clean up temp ref if we used one (best-effort, not critical if it fails)
342		if usedTempRef {
343			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
344		}
345	
346		return nil
347	}
348	
349	// getMergeBase returns the merge base hash of two commits, or an error if they
350	// have no common ancestor.
351	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
352		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
353		defer cancel()
354	
355		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
356		cmd.Dir = repoPath
357		output, err := cmd.Output()
358		if err != nil {
359			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
360		}
361	
362		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
363	}
364	
365	// collectCommitsSince returns non-merge commits reachable from tip but not from
366	// exclude, ordered oldest-first in topological order.
367	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
368		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
369		defer cancel()
370	
371		// cherryPickOnto computes each commit's delta against its first parent, so
372		// replaying merge commits would incorrectly re-apply changes that arrived via
373		// non-first-parent history. Limit the replay set to non-merge commits.
374		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
375		cmd.Dir = repoPath
376		output, err := cmd.Output()
377		if err != nil {
378			return nil, fmt.Errorf("git rev-list failed: %w", err)
379		}
380	
381		lines := strings.Fields(string(output))
382		if len(lines) > MaxCommitTraversalDepth {
383			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
384		}
385	
386		commits := make([]*object.Commit, 0, len(lines))
387		for _, line := range lines {
388			hash := plumbing.NewHash(line)
389			commit, commitErr := repo.CommitObject(hash)
390			if commitErr != nil {
391				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
392			}
393			if len(commit.ParentHashes) > 1 {
394				continue
395			}
396			commits = append(commits, commit)
397		}
398	
399		return commits, nil
400	}
401	
402	// startProgressDots prints dots to w every second until the returned stop function
403	// is called. The stop function prints the given suffix and a newline.
404	func startProgressDots(w io.Writer) func(suffix string) {
405		done := make(chan struct{})
406		stopped := make(chan struct{})
407		go func() {
408			defer close(stopped)
409			ticker := time.NewTicker(time.Second)
410			defer ticker.Stop()
411			for {
412				select {
413				case <-done:
414					return
415				case <-ticker.C:
416					fmt.Fprint(w, ".")
417				}
418			}
419		}()
420		return func(suffix string) {
421			close(done)
422			<-stopped // Wait for goroutine to finish before writing suffix
423			fmt.Fprintln(w, suffix)
424		}
425	}
426	
427	// isURL returns true if the target looks like a URL rather than a git remote name.
428	func isURL(target string) bool {
429		return strings.Contains(target, "://") || strings.Contains(target, "@")
430	}
431	
432	// createMergeCommitCommon creates a merge commit with multiple parents.
433	func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
434		authorName, authorEmail := GetGitAuthorFromRepo(repo)
435		now := time.Now()
436		sig := object.Signature{
437			Name:  authorName,
438			Email: authorEmail,
439			When:  now,
440		}
441	
442		commit := &object.Commit{
443			TreeHash:     treeHash,
444			ParentHashes: parents,
445			Author:       sig,
446			Committer:    sig,
447			Message:      message,
448		}
449	
450		obj := repo.Storer.NewEncodedObject()
451		if err := commit.Encode(obj); err != nil {
452			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
453		}
454	
455		hash, err := repo.Storer.SetEncodedObject(obj)
456		if err != nil {
457			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
458		}
459	
