209	// detectRemoteOnlyArchives discovers archived generation refs on the remote
210	// that don't exist locally. Returns them sorted ascending (oldest first).
211	func detectRemoteOnlyArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
212		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
213		defer cancel()
214	
215		cmd := CheckpointGitCommand(ctx, target, "ls-remote", target, paths.V2FullRefPrefix+"*")
216		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
217		output, err := cmd.Output()
218		if err != nil {
219			return nil, fmt.Errorf("ls-remote failed: %w", err)
220		}
221	
222		var remoteOnly []string
223		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
224			if line == "" {
225				continue
226			}
227			parts := strings.Fields(line)
228			if len(parts) < 2 {
229				continue
230			}
231			refName := parts[1]
232			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
233			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
234				continue
235			}
236			// Only check for existence, not hash equality. A locally-present archive
237			// could be stale if another machine updated it via rotation conflict recovery,
238			// but that's unlikely and the checkpoints are still on /main regardless.
239			if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
240				remoteOnly = append(remoteOnly, suffix)
241			}
242		}
243	
244		sort.Strings(remoteOnly)
245		return remoteOnly, nil
246	}
247	
248	// handleRotationConflict handles the case where remote /full/current was rotated.
249	// Merges local /full/current into the latest remote archived generation to avoid
250	// duplicating checkpoint data, then adopts remote's /full/current as local.
251	func handleRotationConflict(ctx context.Context, target, fetchTarget string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
252		// Use the latest remote-only archive
253		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
254		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
255	
256		// Fetch the latest archived generation
257		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
258		archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
259		fetchArgs := AppendFetchFilterArgs(ctx, []string{"fetch", "--no-tags", fetchTarget, archiveRefSpec})
260		fetchCmd := CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
261		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
262		if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
263			return fmt.Errorf("fetch archived generation failed: %s", output)
264		}
265		defer func() {
266			_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
267		}()
268	
269		// Get archived generation state
270		archiveRef, err := repo.Reference(archiveTmpRef, true)
271		if err != nil {
272			return fmt.Errorf("failed to get archived ref: %w", err)
273		}
274		archiveCommit, err := repo.CommitObject(archiveRef.Hash())
275		if err != nil {
276			return fmt.Errorf("failed to get archive commit: %w", err)
277		}
278		archiveTree, err := archiveCommit.Tree()
279		if err != nil {
280			return fmt.Errorf("failed to get archive tree: %w", err)
281		}
282	
283		// Get local /full/current state
284		localRef, err := repo.Reference(refName, true)
285		if err != nil {
286			return fmt.Errorf("failed to get local ref: %w", err)
287		}
288		localCommit, err := repo.CommitObject(localRef.Hash())
289		if err != nil {
290			return fmt.Errorf("failed to get local commit: %w", err)
291		}
292		localTree, err := localCommit.Tree()
293		if err != nil {
294			return fmt.Errorf("failed to get local tree: %w", err)
295		}
296	
297		// Tree-merge local /full/current into archived generation.
298		// Git content-addressing deduplicates shared shard paths automatically.
299		entries := make(map[string]object.TreeEntry)
300		if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
301			return fmt.Errorf("failed to flatten archive tree: %w", err)
302		}
303		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
304			return fmt.Errorf("failed to flatten local tree: %w", err)
305		}
306	
307		// Update generation.json timestamps if present in the merged tree.
308		// Use the local /full/current HEAD commit time as the newest checkpoint time
309		// (more accurate than time.Now() for cleanup scheduling).
310		if genEntry, exists := entries[paths.GenerationFileName]; exists {
311			if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
312				entries[paths.GenerationFileName] = updatedEntry
313			} else {
314				logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
315					slog.String("error", updateErr.Error()),
316				)
317			}
318		}
319	
320		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
321		if err != nil {
322			return fmt.Errorf("failed to build merged tree: %w", err)
323		}
324	
325		// Create commit parented on archive's commit (fast-forward)
326		mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
327			[]plumbing.Hash{archiveRef.Hash()},
328			"Merge local checkpoints into archived generation")
329		if err != nil {
330			return fmt.Errorf("failed to create merge commit: %w", err)
331		}
332	
333		// Update local archived ref and push it
334		newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
335		if err := repo.Storer.SetReference(newArchiveRef); err != nil {
336			return fmt.Errorf("failed to update archive ref: %w", err)
337		}
338	
339		if _, pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
340			return fmt.Errorf("failed to push updated archive: %w", pushErr)
341		}
342	
343		// Adopt remote's /full/current as local
344		remoteRef, err := repo.Reference(tmpRefName, true)
345		if err != nil {
346			return fmt.Errorf("failed to get fetched /full/current: %w", err)
347		}
348		adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
349		if err := repo.Storer.SetReference(adoptedRef); err != nil {
350			return fmt.Errorf("failed to adopt remote /full/current: %w", err)
351		}
352	
353		return nil
354	}
355	
356	// updateGenerationTimestamps reads generation.json from a blob, updates
357	// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
358	// an updated tree entry. Uses the local commit timestamp rather than
359	// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
360	func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
361		blob, err := repo.BlobObject(genBlobHash)
362		if err != nil {
363			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
364		}
365		reader, err := blob.Reader()
366		if err != nil {
367			return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
368		}
369		defer reader.Close()
370	
371		data, err := io.ReadAll(reader)
372		if err != nil {
373			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
374		}
375	
376		var gen checkpoint.GenerationMetadata
377		if err := json.Unmarshal(data, &gen); err != nil {
378			return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
379		}
380	
381		if newestFromLocal.After(gen.NewestCheckpointAt) {
382			gen.NewestCheckpointAt = newestFromLocal
383		}
384	
385		updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
386		if err != nil {
387			return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
388		}
389	
390		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
391		if err != nil {
392			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
393		}
394	
395		return object.TreeEntry{
396			Name: paths.GenerationFileName,
397			Mode: filemode.Regular,
398			Hash: newBlobHash,
399		}, nil
400	}
401	
402	// pushV2Refs pushes v2 checkpoint refs to the target.
403	// Pushes /main, /full/current, and the latest archived generation (if any).
404	// Older archived generations are immutable and were pushed when created.
405	func pushV2Refs(ctx context.Context, target string) {
406		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
407		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally
408	
409		// Push only the latest archived generation (most likely to be newly created)
410		repo, err := OpenRepository(ctx)
411		if err != nil {
412			return
413		}
414		store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
415		archived, err := store.ListArchivedGenerations()
416		if err != nil || len(archived) == 0 {
417			return
418		}
419		latest := archived[len(archived)-1]
420		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
421	}
422	
423	// shortRefName returns a human-readable short form of a ref name for log output.
424	// e.g., "refs/entire/checkpoints/v2/main" -> "v2/main"
425	func shortRefName(refName plumbing.ReferenceName) string {
426		const prefix = "refs/entire/checkpoints/"
427		s := string(refName)
428		if strings.HasPrefix(s, prefix) {
429			return s[len(prefix):]
430		}
431		return s
432	}
