package testutil

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
)

type skipTB interface {
	Helper()
	Skipf(format string, args ...any)
}

// NewHTTPTestServerOrSkip starts an httptest server, or skips the test if the
// current environment disallows binding a local listener.
func NewHTTPTestServerOrSkip(t skipTB, handler http.Handler) *httptest.Server {
	t.Helper()
	return newHTTPTestServerOrSkip(t, func() *httptest.Server {
		return httptest.NewServer(handler)
	})
}

// NewHTTPSTestServerOrSkip starts an HTTPS httptest server, or skips the test
// if the current environment disallows binding a local listener.
func NewHTTPSTestServerOrSkip(t skipTB, handler http.Handler) *httptest.Server {
	t.Helper()
	return newHTTPTestServerOrSkip(t, func() *httptest.Server {
		return httptest.NewTLSServer(handler)
	})
}

func newHTTPTestServerOrSkip(t skipTB, start func() *httptest.Server) (srv *httptest.Server) {
	t.Helper()

	defer func() {
		if r := recover(); r != nil {
			msg := fmt.Sprint(r)
			if strings.Contains(msg, "httptest: failed to listen on a port") {
				t.Skipf("skipping test: local listeners unavailable in this environment: %s", msg)
			}
			panic(r)
		}
	}()

	return start()
}

